1	package com.maritime.platform.gateway.filter;
2	
3	import org.springframework.core.Ordered;
4	
5	/**
6	 * Defines the execution order for the gateway filter chain.
7	 * <p>
8	 * Lower values run first. TraceId must run before header strip
9	 * so the incoming trace ID can be captured before it is removed.
10	 * Header strip must run before all other logic so no filter sees
11	 * client-supplied internal headers.
12	 */
13	public final class GatewayFilterOrder {
14	
15		private GatewayFilterOrder() {
16		}
17	
18		public static final int TRACE_ID = Ordered.HIGHEST_PRECEDENCE;
19	
20		public static final int UNTRUSTED_HEADER_STRIP = Ordered.HIGHEST_PRECEDENCE + 5;
21	
22		public static final int REQUEST_LOG = Ordered.HIGHEST_PRECEDENCE + 10;
23	
24		public static final int SECURITY_POLICY = Ordered.HIGHEST_PRECEDENCE + 20;
25	
26		public static final int JWT_AUTHENTICATION = Ordered.HIGHEST_PRECEDENCE + 25;
27	
28		public static final int CONTEXT_HEADER_INJECTION = Ordered.HIGHEST_PRECEDENCE + 30;
29	}
