52	        if (jwt.enabled) {
53	            if (jwt.secret == null || jwt.secret.isBlank()) {
54	                throw new IllegalStateException(
55	                        "maritime.gateway.security.jwt.secret must not be blank when jwt.enabled=true");
56	            }
57	            if (jwt.issuer == null || jwt.issuer.isBlank()) {
58	                throw new IllegalStateException(
59	                        "maritime.gateway.security.jwt.issuer must not be blank when jwt.enabled=true");
60	            }
61	        }
62	        if (hmac.enabled) {
63	            if (hmac.timestampTolerance == null || hmac.timestampTolerance.isNegative()) {
64	                throw new IllegalStateException(
65	                        "maritime.gateway.security.hmac.timestamp-tolerance must be a positive duration when hmac.enabled=true");
66	            }
67	            if (hmac.nonceTtl == null || hmac.nonceTtl.isNegative()) {
68	                throw new IllegalStateException(
69	                        "maritime.gateway.security.hmac.nonce-ttl must be a positive duration when hmac.enabled=true");
70	            }
71	        }
72	    }
