371			@Test
372			@DisplayName("public path with NONE auth traverses all filters without error")
373			void publicPathTraversesAllFilters() {
374				GatewaySecurityProperties props = new GatewaySecurityProperties();
375				props.getPublicPaths().add("/public/**");
376				RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props);
377				resolver.afterPropertiesSet();
378	
379				TraceIdGatewayFilter trace = new TraceIdGatewayFilter();
380				UntrustedHeaderStripFilter strip = new UntrustedHeaderStripFilter();
381				RequestLogGatewayFilter logFilter = new RequestLogGatewayFilter();
382				RouteSecurityPolicyFilter security = new RouteSecurityPolicyFilter(resolver);
383				ContextHeaderInjectionFilter inject = new ContextHeaderInjectionFilter();
384	
385				MockServerWebExchange exchange = MockServerWebExchange.from(
386						MockServerHttpRequest.get("/public/health")
387								.header("X-Internal-Call", "1")
388								.header("X-User-Id", "attacker"));
389	
390				// Run filters in order
391				AtomicReference<ServerWebExchange> afterTrace = new AtomicReference<>();
392				trace.filter(exchange, capturingChain(afterTrace)).block();
393				ServerWebExchange e1 = afterTrace.get();
394	
395				AtomicReference<ServerWebExchange> afterStrip = new AtomicReference<>();
396				strip.filter(e1, capturingChain(afterStrip)).block();
397				ServerWebExchange e2 = afterStrip.get();
398	
399				AtomicReference<ServerWebExchange> afterLog = new AtomicReference<>();
400				logFilter.filter(e2, capturingChain(afterLog)).block();
401				ServerWebExchange e3 = afterLog.get();
402	
403				AtomicReference<ServerWebExchange> afterSecurity = new AtomicReference<>();
404				security.filter(e3, capturingChain(afterSecurity)).block();
405				ServerWebExchange e4 = afterSecurity.get();
406	
407				AtomicReference<ServerWebExchange> afterInjection = new AtomicReference<>();
408				inject.filter(e4, capturingChain(afterInjection)).block();
409				ServerWebExchange e5 = afterInjection.get();
410	
411				// TraceId is present
412				assertThat((String) e5.getAttribute(TraceIdGatewayFilter.TRACE_ID_ATTR)).isNotNull();
413	
414				// Internal headers are stripped
415				assertThat(e5.getRequest().getHeaders().getFirst("X-Internal-Call")).isNull();
416				assertThat(e5.getRequest().getHeaders().getFirst("X-User-Id")).isNull();
417	
418				// Security policy resolved
419				RouteSecurityPolicy policy = e5.getAttribute(RouteSecurityPolicyFilter.POLICY_ATTR);
420				assertThat(policy).isNotNull();
421				assertThat(policy.getAuthMode()).isEqualTo(AuthMode.NONE);
422	
423				// Response has trace ID
424				assertThat(e5.getResponse().getHeaders().getFirst(TraceIdGatewayFilter.TRACE_ID_HEADER))
425						.isNotNull();
426			}
