442			@Test
443			@DisplayName("security policy stores correct matched rule id for resolved path")
444			void policyRuleId() {
445				GatewaySecurityProperties props = new GatewaySecurityProperties();
446				props.getPublicPaths().add("/actuator/**");
447				RouteSecurityPolicyResolver resolver = new RouteSecurityPolicyResolver(props);
448				resolver.afterPropertiesSet();
449	
450				RouteSecurityPolicyFilter filter = new RouteSecurityPolicyFilter(resolver);
451				MockServerWebExchange exchange = MockServerWebExchange.from(
452						MockServerHttpRequest.get("/actuator/health"));
453				AtomicReference<ServerWebExchange> captured = new AtomicReference<>();
454	
455				filter.filter(exchange, capturingChain(captured)).block();
