463		// ---------- helpers ----------
464	
465		private static GatewayFilterChain capturingChain(AtomicReference<ServerWebExchange> ref) {
466			return exchange -> {
467				if (ref != null) {
468					ref.set(exchange);
469				}
470				return Mono.empty();
471			};
472		}
