65		private String createToken(Instant issuedAt, Instant expiration, String userId, String sessionId) {
66			return Jwts.builder()
67					.issuer(ISSUER)
68					.subject(userId)
69					.claim("userId", userId)
70					.claim("userName", "TestUser")
71					.claim("sessionId", sessionId)
72					.claim("activeOrgCode", "ORG001")
73					.issuedAt(Date.from(issuedAt))
74					.expiration(Date.from(expiration))
75					.signWith(signingKey)
76					.compact();
77		}
